mapper.select:
SELECT 
  FROM tb_notification_pref
 WHERE user_id           = #{userId}
   AND notification_type = #{notificationType}
 LIMIT 1

mapper.update:
UPDATE tb_notification_pref SET
  channel_inapp_yn=#{channelInappYn},
  channel_email_yn=#{channelEmailYn},
  updated_by=#{updatedBy}, updated_ip=#{updatedIp}, updated_at=NOW()
WHERE user_id           = #{userId}
   AND notification_type = #{notificationType}
